"""Storage adapters. All object names are generated by the backup service."""
import base64
import http.client
import re
import urllib.error
import urllib.request
import xml.etree.ElementTree as ET
from datetime import datetime, timezone
from urllib.parse import quote, unquote, urlsplit

NAME = re.compile(r'(?:team-ledger|before-restore)-\d{8}T\d{6}Z-[0-9a-f]{8}\.zip')
TIMEOUT = 30


class StorageError(Exception):
    pass


def valid_name(name):
    return isinstance(name, str) and NAME.fullmatch(name) is not None


def bounded_copy(source, destination, maximum):
    total = 0
    with destination.open('wb') as output:
        while chunk := source.read(1024 * 1024):
            total += len(chunk)
            if total > maximum:
                raise StorageError('备份文件超过服务器允许的大小')
            output.write(chunk)


class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


class WebDAV:
    def __init__(self, conf):
        self.base = conf['url'].rstrip('/') + '/'
        self.prefix = conf['prefix'].strip('/')
        token = base64.b64encode(f"{conf['username']}:{conf['password']}".encode()).decode()
        self.headers = {'Authorization': 'Basic ' + token}
        self.opener = urllib.request.build_opener(NoRedirect())

    @property
    def folder(self):
        suffix = '/'.join(quote(p, safe='') for p in self.prefix.split('/') if p)
        return self.base + (suffix + '/' if suffix else '')

    def request(self, method, url, data=None, headers=None):
        request = urllib.request.Request(url, data=data, method=method,
                                         headers={**self.headers, **(headers or {})})
        try:
            return self.opener.open(request, timeout=TIMEOUT)
        except urllib.error.HTTPError as exc:
            status = exc.code
            exc.close()
            raise StorageError(f'WebDAV 请求失败（HTTP {status}），请检查地址、权限及登录信息') from None
        except (OSError, ValueError, http.client.HTTPException):
            raise StorageError('WebDAV 连接失败，请检查地址、网络及证书') from None

    def ensure_folder(self):
        current = self.base.rstrip('/')
        for part in self.prefix.split('/'):
            if not part:
                continue
            current += '/' + quote(part, safe='')
            # An existing collection normally returns 405. Verify it with PROPFIND
            # rather than treating every 405 as a usable directory.
            try:
                with self.request('MKCOL', current + '/'):
                    pass
            except StorageError:
                self._list(current + '/', depth='0')

    def _list(self, url, depth='1'):
        body = b'<?xml version="1.0"?><d:propfind xmlns:d="DAV:"><d:prop><d:resourcetype/><d:getcontentlength/><d:getlastmodified/></d:prop></d:propfind>'
        try:
            with self.request('PROPFIND', url, body, {'Depth': depth, 'Content-Type': 'application/xml'}) as response:
                payload = response.read(8 * 1024 * 1024 + 1)
        except (OSError, http.client.HTTPException):
            raise StorageError('读取 WebDAV 目录失败，请检查网络连接') from None
        if len(payload) > 8 * 1024 * 1024 or b'<!DOCTYPE' in payload.upper() or b'<!ENTITY' in payload.upper():
            raise StorageError('WebDAV 目录响应无效或过大')
        try:
            return ET.fromstring(payload)
        except ET.ParseError:
            raise StorageError('WebDAV 目录响应格式不正确') from None

    def list(self):
        root = self._list(self.folder)
        result = []
        folder_path = unquote(urlsplit(self.folder).path).rstrip('/') + '/'
        for row in root.findall('{DAV:}response'):
            href = row.findtext('{DAV:}href', '')
            path = unquote(urlsplit(href).path)
            if not path.startswith(folder_path):
                continue
            name = path[len(folder_path):]
            if not valid_name(name):
                continue
            prop = None
            for part in row.findall('{DAV:}propstat'):
                if ' 200 ' in part.findtext('{DAV:}status', ''):
                    prop = part.find('{DAV:}prop')
                    break
            if prop is None or prop.find('.//{DAV:}collection') is not None:
                continue
            size = prop.findtext('{DAV:}getcontentlength', '0')
            result.append({'name': name, 'size': int(size) if size.isdigit() else 0,
                           'modified_at': prop.findtext('{DAV:}getlastmodified', '')})
        return sorted(result, key=lambda item: item['name'], reverse=True)

    def upload(self, name, path):
        self.ensure_folder()
        # urllib sends the file in chunks with an explicit length.
        with path.open('rb') as stream:
            with self.request('PUT', self.folder + quote(name), stream,
                              {'Content-Length': str(path.stat().st_size), 'Content-Type': 'application/zip'}):
                pass

    def download(self, name, destination, maximum):
        try:
            with self.request('GET', self.folder + quote(name)) as response:
                bounded_copy(response, destination, maximum)
        except (OSError, http.client.HTTPException):
            raise StorageError('WebDAV 下载失败，请检查网络及服务器存储空间') from None

    def delete(self, name):
        with self.request('DELETE', self.folder + quote(name)):
            pass


class S3:
    def __init__(self, conf):
        try:
            import boto3
            from botocore.config import Config
        except ImportError:
            raise StorageError('S3 依赖未安装，请更新服务器依赖') from None
        self.bucket = conf['bucket']
        self.prefix = conf['prefix'].strip('/')
        self.client = boto3.client(
            's3', endpoint_url=conf['endpoint'] or None, region_name=conf['region'],
            aws_access_key_id=conf['access_key_id'], aws_secret_access_key=conf['secret_access_key'],
            config=Config(signature_version='s3v4', connect_timeout=10, read_timeout=TIMEOUT,
                          retries={'max_attempts': 2, 'mode': 'standard'},
                          request_checksum_calculation='when_required',
                          response_checksum_validation='when_required',
                          s3={'addressing_style': 'path' if conf['path_style'] else 'virtual'}))

    def key(self, name=''):
        return (self.prefix + '/' if self.prefix else '') + name

    def _call(self, method, **kwargs):
        try:
            return getattr(self.client, method)(Bucket=self.bucket, **kwargs)
        except Exception:
            # SDK error messages can include endpoints or credential identifiers.
            raise StorageError('S3 请求失败，请检查 Endpoint、区域、存储桶、凭据及读写权限') from None

    def list(self):
        result, token = [], None
        while True:
            page = self._call('list_objects_v2', Prefix=self.key(), **({'ContinuationToken': token} if token else {}))
            for item in page.get('Contents', []):
                name = item['Key'][len(self.key()):]
                if valid_name(name):
                    modified = item.get('LastModified', datetime.now(timezone.utc))
                    result.append({'name': name, 'size': item.get('Size', 0),
                                   'modified_at': modified.isoformat()})
            if not page.get('IsTruncated'):
                break
            token = page.get('NextContinuationToken')
            if not token:
                raise StorageError('S3 目录分页响应不正确')
        return sorted(result, key=lambda item: item['name'], reverse=True)

    def upload(self, name, path):
        with path.open('rb') as stream:
            self._call('put_object', Key=self.key(name), Body=stream, ContentType='application/zip')

    def download(self, name, destination, maximum):
        response = self._call('get_object', Key=self.key(name))
        try:
            bounded_copy(response['Body'], destination, maximum)
        except StorageError:
            raise
        except Exception:
            raise StorageError('S3 下载失败，请检查网络及服务器存储空间') from None
        finally:
            response['Body'].close()

    def delete(self, name):
        self._call('delete_object', Key=self.key(name))


def remote(target, conf):
    return WebDAV(conf['webdav']) if target == 'webdav' else S3(conf['s3'])
